private lateinit var memo: MutableMap<Int, Long>

private fun fib(n: Int): Long {
    if (n < 2) return n.toLong()
    return memo.computeIfAbsent(n) { k -> fib(k - 1) + fib(k - 2) }   // modifies the map from inside compute
}

fun main() {
